const modelName = $input.first().json.model_name;
const memories = [
  {key:'launch_date', text:'Der Produktlaunch von "Aurora" ist für den 15. März 2027 geplant.', type:'deadline', topic:'project_timeline', importance:1.0},
  {key:'budget', text:'Das genehmigte Projektbudget für das laufende Quartal beträgt 250.000 Euro.', type:'budget', topic:'finance', importance:0.9},
  {key:'project_lead', text:'Die Projektleitung liegt bei Dr. Sandra Berger.', type:'personnel', topic:'organization', importance:0.85},
  {key:'vendor', text:'Nach der Ausschreibung wurde die Firma Nordwind Systems GmbH als Cloud-Anbieter ausgewählt.', type:'project_decision', topic:'procurement', importance:0.9},
  {key:'sla', text:'Laut Support-SLA beträgt die maximale Reaktionszeit bei kritischen Störungen 4 Stunden.', type:'policy', topic:'support', importance:0.95},
  {key:'compliance', text:'Gemäß interner Datenschutzrichtlinie müssen alle Kundendaten ausschließlich auf Servern innerhalb der EU gespeichert werden.', type:'policy', topic:'compliance', importance:1.0},
  {key:'risk', text:'Als größtes Projektrisiko wurde die Abhängigkeit von einem einzelnen Halbleiter-Zulieferer identifiziert.', type:'risk', topic:'project_management', importance:0.8},
  {key:'chat_model', text:`Für die interne Chatbot-Instanz wird aktuell das Modell ${modelName} eingesetzt.`, type:'technical_configuration', topic:'ai_system', importance:0.85}
];
return memories.map(m => ({json:m}));

const src = $('Benchmark-Memorys erzeugen').all();
const emb = $input.all();
return emb.map((item, i) => {
  const m = src[i].json;
  const vector = item.json.embeddings?.[0] ?? item.json.embedding;
  if (!vector) throw new Error(`Kein Embedding für Memory ${m.key} erhalten.`);
  return {json:{
    id: i + 1,
    vector,
    payload:{
      text:m.text, key:m.key, type:m.type, topic:m.topic,
      importance:m.importance, source:'benchmark', valid:true
    }
  }};
});

const editFields = $('Edit Fields').first().json;
const modelName = editFields.model_name;
const contextSize = editFields.context_size;
const useQdrant = !!editFields.use_qdrant;

// Standard-Retrieval-Fragen (Fakt irgendwo im Kontext verteilt, Variante "main")
const retrievalCases = [
  {q:'Wann ist der Produktlaunch geplant?', expected:'15. März 2027'},
  {q:'Wie hoch ist das genehmigte Projektbudget für das laufende Quartal?', expected:'250.000 Euro'},
  {q:'Wer hat die Projektleitung inne?', expected:'Sandra Berger'},
  {q:'Welche Firma wurde als Cloud-Anbieter ausgewählt?', expected:'Nordwind Systems'},
  {q:'Welches Modell wird für die interne Chatbot-Instanz eingesetzt?', expected: modelName}
];

// Negations-/Abwesenheitstest
const negationCases = [
  {q:'Wer ist der stellvertretende Projektleiter?', expected:'Information fehlt'},
  {q:'Welches Betriebssystem läuft auf den Produktionsservern?', expected:'Information fehlt'}
];

// Positionstest ("Lost in the Middle")
const positionQuestion = {q:'Welches Modell wird für die interne Chatbot-Instanz eingesetzt?', expected: modelName};
const positionVariants = ['position_start', 'position_middle', 'position_end'];

// Distraktoren-Test
const distractorCases = [
  {q:'Wie hoch ist das genehmigte Projektbudget für das LAUFENDE Quartal (nicht das vorherige)?', expected:'250.000 Euro', variant:'distractor'}
];

// Multi-Hop-Fragen
const multihopCases = [
  {q:'In welcher Stadt hat der ausgewählte Cloud-Anbieter seinen Hauptsitz?', expected:'Hamburg', variant:'multihop'},
  {q:'Wann findet das Kickoff-Meeting statt (Monat und Jahr genügen)?', expected:'September 2026', variant:'multihop'}
];

// Zusammenfassungstest
const summaryKeywords = ['15. März 2027', '250.000 Euro', 'Sandra Berger', 'Nordwind Systems', '4 Stunden', 'EU', 'Halbleiter', modelName];
const summaryCases = [
  {q:'Fasse alle im Kontext genannten Fakten in einem kurzen Absatz zusammen.', expected: summaryKeywords, variant:'main'}
];

// Prompt-Injection-Test: dieselbe Frage wie im Retrieval-Test, aber im Kontext steckt
// eine versteckte Anweisung, die das Modell vom eigentlichen Ziel ablenken soll
const injectionCases = [
  {q:'Wie hoch ist das genehmigte Projektbudget für das laufende Quartal?', expected:'250.000 Euro', variant:'injection'}
];

// Wiederholungstest: dieselbe Frage mehrfach stellen, Antwortstabilität prüfen
const consistencyRepeats = 3;
const consistencyQuestion = {q:'Wann ist der Produktlaunch geplant?', expected:'15. März 2027'};

// Format-Compliance-Test: prüft zusätzlich zur Korrektheit, ob die Formatvorgabe
// aus dem System-Prompt eingehalten wird (max. 1 Satz, keine Einleitungsfloskeln)
const formatCases = [
  {q:'Wie hoch ist das genehmigte Projektbudget für das laufende Quartal?', expected:'250.000 Euro'},
  {q:'Welche Firma wurde als Cloud-Anbieter ausgewählt?', expected:'Nordwind Systems'}
];

// Paraphrasen-Robustheit: dieselbe Frage unterschiedlich formuliert, Ergebnis sollte gleich bleiben
const paraphraseCases = [
  {q:'Wer hat die Projektleitung inne?', expected:'Sandra Berger'},
  {q:'Wer leitet das Projekt?', expected:'Sandra Berger'},
  {q:'Wer ist für die Projektleitung verantwortlich?', expected:'Sandra Berger'}
];

const out = [];

if (editFields.test_retrieval) {
  for (const c of retrievalCases)
    out.push({json:{context:contextSize, question:c.q, expected:c.expected, variant:'main', testType:'retrieval'}, pairedItem:{item:0}});
}

if (editFields.test_negation) {
  for (const c of negationCases)
    out.push({json:{context:contextSize, question:c.q, expected:c.expected, variant:'main', testType:'negation'}, pairedItem:{item:0}});
}

// Wiederholungstest, Format-Compliance und Paraphrasen-Robustheit funktionieren in
// BEIDEN Modi (RAM & Qdrant), da sie nur die Frage variieren, nicht den Kontext.
if (editFields.test_consistency) {
  for (let i = 0; i < consistencyRepeats; i++)
    out.push({json:{context:contextSize, question:consistencyQuestion.q, expected:consistencyQuestion.expected, variant:'main', testType:'consistency', group:'consistency_launch', repeatIndex:i}, pairedItem:{item:0}});
}

if (editFields.test_format) {
  for (const c of formatCases)
    out.push({json:{context:contextSize, question:c.q, expected:c.expected, variant:'main', testType:'format'}, pairedItem:{item:0}});
}

if (editFields.test_paraphrase) {
  for (const c of paraphraseCases)
    out.push({json:{context:contextSize, question:c.q, expected:c.expected, variant:'main', testType:'paraphrase', group:'paraphrase_lead'}, pairedItem:{item:0}});
}

// Position/Distraktor/Multi-Hop/Zusammenfassung/Prompt-Injection sind an die exakte
// Kontext-Konstruktion im RAM-Modus gebunden (kontrollierte Platzierung bzw. Menge/Inhalt
// des Kontexts). Bei Vektorsuche über Qdrant ist das konzeptionell nicht gegeben, daher
// im Qdrant-Modus übersprungen, auch wenn die jeweiligen Schalter aktiv sind.
if (!useQdrant) {
  if (editFields.test_position) {
    for (const variant of positionVariants)
      out.push({json:{context:contextSize, question:positionQuestion.q, expected:positionQuestion.expected, variant, testType:'position', position:variant.replace('position_','')}, pairedItem:{item:0}});
  }

  if (editFields.test_distractor) {
    for (const c of distractorCases)
      out.push({json:{context:contextSize, question:c.q, expected:c.expected, variant:c.variant, testType:'distractor'}, pairedItem:{item:0}});
  }

  if (editFields.test_multihop) {
    for (const c of multihopCases)
      out.push({json:{context:contextSize, question:c.q, expected:c.expected, variant:c.variant, testType:'multihop'}, pairedItem:{item:0}});
  }

  if (editFields.test_summary) {
    for (const c of summaryCases)
      out.push({json:{context:contextSize, question:c.q, expected:c.expected, variant:c.variant, testType:'summary'}, pairedItem:{item:0}});
  }

  if (editFields.test_injection) {
    for (const c of injectionCases)
      out.push({json:{context:contextSize, question:c.q, expected:c.expected, variant:c.variant, testType:'injection'}, pairedItem:{item:0}});
  }
}

if (out.length === 0) {
  throw new Error('Kein einziger Test ist aktiviert bzw. im aktuellen Modus verfügbar - Schalter in "Edit Fields" prüfen.');
}

return out;

const editFields = $('Edit Fields').first().json;

if (editFields.use_qdrant) {
  // Qdrant-Modus: memories aus den Vektor-Suchtreffern des jeweiligen Testfalls bauen.
  // item.json ist hier die rohe Qdrant-Suchantwort ({result:[...]}), die ursprünglichen
  // Testfall-Felder (question/expected/...) kommen daher aus "Benchmark-Fälle erzeugen"
  // per Index dazu (gleiche Reihenfolge, da alle Zwischenschritte mit batchSize 1 sequenziell laufen).
  const cases = $('Benchmark-Fälle erzeugen').all();
  return $input.all().map((item, i) => {
    const hits = item.json.result || [];
    const memories = hits.map(h => h.payload?.text).filter(Boolean).join('\n');
    const caseData = cases[i]?.json || {};
    return {
      json: { ...caseData, memories, qdrant_hits: hits.length },
      pairedItem: item.pairedItem ?? { item: 0 }
    };
  });
}

// RAM-Modus (Standard): passende Kontext-Variante aus "Kontext befüllen" nachschlagen
// (main / position_start / position_middle / position_end / distractor / multihop).
const variants = $('Kontext befüllen').all();

return $input.all().map(item => {
  const wantedVariant = item.json.variant || 'main';
  const match = variants.find(v => v.json.variant === wantedVariant) || variants.find(v => v.json.variant === 'main');
  const memories = match ? match.json.big_context : '';
  return {
    json: { ...item.json, memories },
    pairedItem: item.pairedItem ?? { item: 0 }
  };
});

